package org.apache.accumulo.test.ample.metadata;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

import org.apache.accumulo.core.client.ConditionalWriter;
import org.apache.accumulo.core.client.ConditionalWriter.Result;
import org.apache.accumulo.core.client.ConditionalWriter.Status;
import org.apache.accumulo.core.data.ConditionalMutation;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A {@link ConditionalWriterInterceptor} that simulates ambiguous conditional mutation outcomes.
 * For each mutation it randomly chooses one of three outcomes:
 * <ul>
 * <li>Do not write the mutation and return {@link Status#UNKNOWN}.</li>
 * <li>Write the mutation but return {@link Status#UNKNOWN}.</li>
 * <li>Write the mutation and return its actual status.</li>
 * </ul>
 * This exercises code paths that must be able to recover from an {@code UNKNOWN} status regardless
 * of whether the mutation was actually applied.
 */
public class FlakyInterceptor implements ConditionalWriterInterceptor {

  private static final Logger log = LoggerFactory.getLogger(FlakyInterceptor.class);

  @Override
  public Iterator<Result> write(ConditionalWriter writer,
      Iterator<ConditionalMutation> mutations) {
    List<Result> results = new ArrayList<>();
    while (mutations.hasNext()) {
      results.add(write(writer, mutations.next()));
    }
    return results.iterator();
  }

  @Override
  public Result write(ConditionalWriter writer, ConditionalMutation mutation) {
    switch (ThreadLocalRandom.current().nextInt(3)) {
      case 0:
        // Do not write the mutation and return an UNKNOWN status.
        log.debug("Flaky conditional write: skipping write and returning UNKNOWN");
        return new Result(Status.UNKNOWN, mutation, null);
      case 1:
        // Write the mutation but return an UNKNOWN status.
        log.debug("Flaky conditional write: writing but returning UNKNOWN");
        Result written = writer.write(mutation);
        return new Result(Status.UNKNOWN, written.getMutation(), written.getTabletServer());
      default:
        // Write the mutation and return the actual status.
        return writer.write(mutation);
    }
  }
}
