package org.apache.accumulo.test.ample;

import java.util.Map;

import org.apache.accumulo.core.conf.SiteConfiguration;
import org.apache.accumulo.core.metadata.schema.Ample;
import org.apache.accumulo.core.metadata.schema.Ample.DataLevel;
import org.apache.accumulo.server.ServerContext;
import org.apache.accumulo.test.ample.metadata.FlakyInterceptor;
import org.apache.accumulo.test.ample.metadata.TestAmple;

/**
 * A test-only {@link ServerContext} whose {@link #getAmple()} returns an {@link Ample}
 * implementation that intercepts conditional mutations to the metadata and user tablet metadata
 * tables using a {@link FlakyInterceptor}. This simulates ambiguous conditional mutation outcomes so
 * that server code exercising metadata updates can be tested for correct handling of unknown
 * results.
 */
public class FlakyAmpleServerContext extends ServerContext {

  public FlakyAmpleServerContext(SiteConfiguration siteConfig) {
    super(siteConfig);
  }

  @Override
  public Ample getAmple() {
    // Intercept conditional writes for the metadata and user data levels against their real backing
    // tables. The root data level is left untouched.
    Map<DataLevel,String> tables = Map.of(DataLevel.METADATA, DataLevel.METADATA.metaTable(),
        DataLevel.USER, DataLevel.USER.metaTable());
    return TestAmple.create(this, tables, FlakyInterceptor::new);
  }
}
